# Shared garden, original restoration story inspired by The Secret Garden.
@id secret_garden
@title SG_NAME
@projection iso
@ambient farm
@theme farm
@zone city
@flight true
@music farm_theme
@zoom 0.55
@prop V bush_berry
@prop N lantern_post
@prop T tree_blossom_hyggebyen
@prop - fence_x
@prop | fence_z
@prop O well
@marker W warp to=hyggebyen spawn=from_garden label=ZONE_CITY r=0
@marker A spawn name=from_town
@marker P secret_garden kind=path
@marker B secret_garden kind=bench
@marker C secret_garden kind=beds
@marker L secret_garden kind=letter
@marker G secret_garden kind=gate
@marker S sign text=SG_SIGN
@ground
